param([Parameter(Mandatory=$true)][string]$First,[Parameter(Mandatory=$true)][string]$Second)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$p="$root/analysis/parallel-aa-receiver/m6-aoa";if(Test-Path "$p/FROZEN.json"){throw 'M6 already frozen; no overwrite'}
Add-Type -AssemblyName System.IO.Compression.FileSystem
function Tree([string]$path){$path=(Resolve-Path $path).Path;return @(Get-ChildItem -LiteralPath $path -Recurse -File|ForEach-Object {$_.FullName.Substring($path.Length)+'='+(Get-FileHash $_.FullName).Hash}|Sort-Object)}
function ZipMap([string]$path,[bool]$Apk){$z=[IO.Compression.ZipFile]::OpenRead($path);try{return @(foreach($e in $z.Entries|Where-Object {$_.Length-gt0-and(-not$Apk-or$_.FullName-notlike'META-INF/*')}){$s=$e.Open();$sha=[Security.Cryptography.SHA256]::Create();try{$e.FullName+'='+[Convert]::ToHexString($sha.ComputeHash($s))}finally{$s.Dispose();$sha.Dispose()}})|Sort-Object}finally{$z.Dispose()}}
$a=Get-Content "$First/build-report.json" -Raw|ConvertFrom-Json;$b=Get-Content "$Second/build-report.json" -Raw|ConvertFrom-Json
foreach($dir in @($First,$Second)){& "$root/tools/m6/Test-M6StaticPolicy.ps1" -Build $dir|Out-Null}
if($a.DEX-ne$b.DEX-or$a.testResult-ne$b.testResult){throw 'M6 payload/test output differs'}
foreach($dir in @('classes','transcripts')){if(@(Compare-Object (Tree "$First/$dir") (Tree "$Second/$dir")).Count){throw "M6 $dir differs"}}
if(@(Compare-Object (ZipMap "$First/classes.jar" $false) (ZipMap "$Second/classes.jar" $false)).Count-or@(Compare-Object (ZipMap $a.apk $true) (ZipMap $b.apk $true)).Count){throw 'M6 JAR/APK unsigned payload differs'}
$audit=Get-Content "$Second/static-audit.json" -Raw|ConvertFrom-Json;$dest="$p/build/FINAL";New-Item -ItemType Directory -Path $dest -ErrorAction Stop|Out-Null;$apk="$dest/rdx-m6-aoa-only-disabled.apk";Copy-Item -LiteralPath $b.apk -Destination $apk
$f=[ordered]@{schema=1;path=$apk.Substring($root.Length+1).Replace('\','/');sha256=(Get-FileHash $apk).Hash;DEX=$b.DEX;package=$b.package;version=$b.version;versionCode=1;minSdk=22;targetSdk=22;signerSHA256='C001F59B25081DDFC73937155CA3580717E817C45C66E68B9E059737B0B28831';permissions=@();components=$audit.components;modules=$b.modules;classes=$audit.definedClasses;externalAPI22Methods=$audit.externalAPI22Methods;liveExecutionEnabled=$false;build=(Resolve-Path $Second).Path;audit=(Resolve-Path "$Second/static-audit.json").Path;reviewerCertificateSHA256=(Get-FileHash "$p/assets/project-reviewer.cer").Hash;testResult=$b.testResult;M5proofCreated=$false;nextLive='M5 RETRY ONLY';activation='Requires separately reviewed future activation release after signed reviewed M5 PASS + explicit M6 authorization. This build script has no active-build option.'}
$f|ConvertTo-Json -Depth 6|Set-Content "$p/FROZEN.json"
[ordered]@{First=$First;Second=$Second;DEX='IDENTICAL';classes='IDENTICAL';jarEntries='IDENTICAL';apkManifestAssetsResources='IDENTICAL';transcripts='IDENTICAL';testExpectations='IDENTICAL';apkContainersIdentical=$a.sha256-eq$b.sha256;archiveDifferences='ZIP timestamps/signature container metadata only; final copied byte-for-byte from second';live='NOT EXECUTED'}|ConvertTo-Json|Set-Content "$p/reproducibility.json"
$f|ConvertTo-Json -Depth 6
